// AI Quiz Generator: core logic (ported from main.py)

// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const PAT = /^(?:(?:An?|The)\s+)?([A-Za-z][\w\s-]{1,40}?)\s+(is|are|refers to|means)\s+(.+?)\.$/;
let seed = 7; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
const shuffle = a => { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
return input.map(({ notes, count = 6 }) => {
  const facts = notes.split(/(?<=\.)\s+|\n+/).map(s => s.trim().match(PAT)).filter(Boolean)
    .map(m => ({ term: m[1][0].toUpperCase() + m[1].slice(1).trim(), verb: m[2], def: m[3].trim() }));
  const terms = facts.map(f => f.term);
  const questions = facts.slice(0, count).map((f, i) => {
    const others = terms.filter(t => t !== f.term);
    if (i % 2 === 0 && others.length >= 3) return { type: 'MCQ', question: `Which term ${f.verb} ${f.def}?`, options: shuffle([...shuffle([...others]).slice(0, 3), f.term]), answer: f.term };
    return { type: 'Fill in the blank', question: `________ ${f.verb} ${f.def}.`, options: [], answer: f.term };
  });
  const sheet = questions.map((q, i) => `${i + 1}. ${q.question}` + q.options.map((o, j) => `\n   ${'ABCD'[j]}. ${o}`).join('')).join('\n\n');
  return { json: { questions, quiz: sheet, answer_key: questions.map((q, i) => `${i + 1}. ${q.answer}`).join('\n') } };
});
